CREATE TABLE `tob_camera`  (
  `camera_id` bigint NOT NULL AUTO_INCREMENT COMMENT '摄像头id',
  `camera_ip` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '摄像头ip',
