  `frame_rate` int NOT NULL COMMENT '帧率',
  `night_vision` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '夜视能力',
  `connection_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '连接方式',
  `installation_date` datetime NOT NULL COMMENT '安装日期',
  `guarantee_period` datetime NOT NULL COMMENT '质保截止日期',
  `longitude` decimal(10, 7) NOT NULL COMMENT '经度',
